<script lang="ts">import {onMount} from "svelte";import {Plus,X,Pencil} from "@lucide/svelte";import {listCustomers,saveCustomer,updateCustomer} from "../lib/tauri";import type {Customer} from "../lib/types";let customers=$state<Customer[]>([]),error=$state(""),open=$state(false),busy=$state(false),editing=$state<number|null>(null),name=$state(""),cpf=$state(""),phone=$state(""),email=$state("");onMount(async()=>{try{customers=await listCustomers()}catch(cause){error=cause instanceof Error?cause.message:"Falha ao carregar clientes"}});function edit(item:Customer){editing=item.id;name=item.name;cpf=item.cpf_cnpj??"";phone=item.phone??"";email=item.email??"";open=true}function reset(){open=false;editing=null;name=cpf=phone=email=""}async function submit(){busy=true;try{const item=editing===null?await saveCustomer(name,cpf,phone,email):await updateCustomer(editing,name,cpf,phone,email);customers=[item,...customers.filter(c=>c.id!==item.id)];reset()}catch(cause){error=String(cause)}finally{busy=false}}</script>
{#if error && !customers.length}<div class="card card-body"><span class="badge danger">{error}</span></div>{:else}<article class="card"><div class="card-header"><div><h2>Gestão de Clientes</h2><p class="small muted">Cadastro e fidelidade local.</p></div><button class="button" onclick={()=>{editing=null;open=true}}><Plus size={17}/> Adicionar Cliente</button></div><div class="table-wrap"><table><thead><tr><th>Cliente</th><th>CPF/CNPJ</th><th>Telefone</th><th>Pontos</th><th>Ação</th></tr></thead><tbody>{#each customers as customer}<tr><td><strong>{customer.name}</strong><br/><small class="muted">{customer.email??""}</small></td><td>{customer.cpf_cnpj??"—"}</td><td>{customer.phone??"—"}</td><td><span class="badge">{customer.points} pts</span></td><td><button class="icon-button" aria-label="Editar cliente" onclick={()=>edit(customer)}><Pencil size={16}/></button></td></tr>{/each}</tbody></table></div></article>{/if}
{#if open}<div class="modal-backdrop"><form class="modal card" onsubmit={(e)=>{e.preventDefault();submit()}}><div class="card-header"><h2>{editing===null?"Novo cliente":"Editar cliente"}</h2><button type="button" class="icon-button" onclick={reset}><X size={18}/></button></div><div class="card-body form-grid"><label class="wide">Nome<input class="input" required bind:value={name}/></label><label>CPF/CNPJ<input class="input" bind:value={cpf}/></label><label>Telefone<input class="input" bind:value={phone}/></label><label class="wide">E-mail<input class="input" type="email" bind:value={email}/></label></div><div class="card-footer modal-actions"><button type="button" class="button secondary" onclick={reset}>Cancelar</button><button class="button" disabled={busy}>Salvar</button></div></form></div>{/if}
